mapper.select:
SELECT
(SELECT COUNT(*) FROM rbac_authorization_change c WHERE c.id=#{grantChangeId} AND c.assignment_id=#{id}
AND c.target_user_id=#{userId} AND c.action='GRANT' AND c.snapshot_version=1
AND JSON_UNQUOTE(JSON_EXTRACT(c.after_snapshot,'$.id'))=#{id}
AND JSON_UNQUOTE(JSON_EXTRACT(c.after_snapshot,'$.userId'))=CAST(#{userId} AS CHAR)
AND JSON_UNQUOTE(JSON_EXTRACT(c.after_snapshot,'$.roleCode'))=#{roleCode}
AND JSON_UNQUOTE(JSON_EXTRACT(c.after_snapshot,'$.namespace'))=#{namespace}
AND JSON_UNQUOTE(JSON_EXTRACT(c.after_snapshot,'$.scopeType'))=#{scopeType}
AND JSON_UNQUOTE(JSON_EXTRACT(c.after_snapshot,'$.version'))=#{version}
AND JSON_UNQUOTE(JSON_EXTRACT(c.after_snapshot,'$.grantChangeId'))=#{grantChangeId}
AND JSON_EXTRACT(c.receipt,'$.assignment')=c.after_snapshot
AND JSON_UNQUOTE(JSON_EXTRACT(c.receipt,'$.assignment.id'))=#{id}
AND JSON_UNQUOTE(JSON_EXTRACT(c.receipt,'$.changeId'))=#{grantChangeId}
AND JSON_UNQUOTE(JSON_EXTRACT(c.receipt,'$.action'))='GRANT') ordinary_grants,
(SELECT COUNT(*) FROM rbac_offline_effect e WHERE e.id=#{grantChangeId} AND e.assignment_id=#{id} AND
e.user_id=#{userId}) offline_grants

choose.otherwise:
WITH requested AS (
SELECT CAST(#{a.id} AS CHAR(36)) COLLATE utf8mb4_0900_bin requested_id, CAST(#{a.grantChangeId} AS CHAR(36)) COLLATE utf8mb4_0900_bin requested_grant_id
), unresolved AS ( SELECT r.requested_id,r.requested_grant_id FROM requested r WHERE NOT EXISTS(SELECT 1 FROM rbac_offline_effect e WHERE e.assignment_id=r.requested_id) ) SELECT r.requested_id,r.requested_grant_id,e.id effect_id,e.user_id,e.assignment_id,e.before_snapshot,e.after_snapshot, o.id operation_id,o.kind,o.snapshot_version,o.receipt,o.occurred_at FROM requested r JOIN rbac_offline_effect e ON e.assignment_id=r.requested_id LEFT JOIN rbac_offline_operation o ON o.id=e.operation_id UNION ALL SELECT r.requested_id,r.requested_grant_id,e.id,e.user_id,e.assignment_id,e.before_snapshot,e.after_snapshot, o.id,o.kind,o.snapshot_version,o.receipt,o.occurred_at FROM requested r JOIN rbac_offline_effect e ON e.id=r.requested_grant_id LEFT JOIN rbac_offline_operation o ON o.id=e.operation_id WHERE NOT(e.assignment_id <=> r.requested_id) UNION ALL SELECT r.requested_id,r.requested_grant_id,NULL,NULL,j.assignment_id,NULL,NULL,o.id,o.kind,o.snapshot_version,o.receipt,o.occurred_at FROM rbac_offline_operation o STRAIGHT_JOIN JSON_TABLE(o.receipt,'$.effects[*]' COLUMNS(assignment_id VARCHAR(36) PATH '$.assignmentId' NULL ON EMPTY)) j STRAIGHT_JOIN unresolved r ON j.assignment_id COLLATE utf8mb4_0900_ai_ci=r.requested_id COLLATE utf8mb4_0900_ai_ci WHERE EXISTS(SELECT 1 FROM unresolved)

mapper.select:
SELECT

FROM rbac_user_role_assignment
WHERE user_id=#{userId} AND granted_at <= #{evaluatedAt}

    AND revoked_at IS NOT NULL


    AND revoked_at IS NULL AND expires_at <= #{evaluatedAt}


    AND revoked_at IS NULL AND (expires_at IS NULL OR expires_at > #{evaluatedAt})


    AND role_code=#{roleCode}


    AND namespace=#{namespace}


    AND (granted_at < #{highTime} OR (granted_at=#{highTime} AND id <= #{highId}))


    AND (granted_at < #{lastTime} OR (granted_at=#{lastTime} AND id < #{lastId}))

ORDER BY granted_at DESC,id DESC LIMIT #{limit}

SELECT id,operation_id,actor_user_id,target_user_id,assignment_id,action,reason,snapshot_version,
before_snapshot,after_snapshot,occurred_at
FROM rbac_authorization_change WHERE publication_order <= #{highWater}

    AND actor_user_id=#{actor}


    AND target_user_id=#{target}


    AND assignment_id=#{assignment}


    AND action=#{action}


    AND occurred_at >= #{after}


    AND occurred_at < #{before}


    AND (occurred_at < #{lastTime} OR (occurred_at=#{lastTime} AND id < #{lastId}))

ORDER BY occurred_at DESC,id DESC LIMIT #{limit}
